import sqlite3
import subprocess

DB = "/var/data/logistics.db"
ROLES = {"viewer", "dispatcher", "admin"}


def grant_carrier_portal_access(user_id: str, carrier_code: str, role: str) -> dict:
    if role not in ROLES:
        return {"ok": False, "error": "invalid role"}
    con = sqlite3.connect(DB)
    cur = con.cursor()
    row = cur.execute(
        "SELECT 1 FROM carriers WHERE code = ?", (carrier_code,)
    ).fetchone()
    if not row:
        con.close()
        return {"ok": False, "error": "unknown carrier"}
    cur.execute(
        "INSERT OR REPLACE INTO portal_roles (user_id, carrier_code, role) VALUES (?, ?, ?)",
        (user_id, carrier_code, role),
    )
    con.commit()
    con.close()
    p = subprocess.run(
        ["/opt/logistics/bin/sync_portal_acl", "--user", user_id, "--carrier", carrier_code],
        capture_output=True,
        text=True,
        timeout=60,
    )
    return {"ok": p.returncode == 0, "output": p.stdout.strip()}
